 21	import com.pousadamarealta.service.event.listeners.FinanceNotificationListener;
 22	import com.pousadamarealta.service.event.listeners.GuestNotificationListener;
 23	import com.pousadamarealta.service.event.listeners.HousekeepingNotificationListener;
 24	import io.javalin.Javalin;
 25	import io.javalin.json.JavalinJackson;
 26	
 27	public class App {
 28	    public static void main(String[] args) {
 29	        String dbUrl = getEnv("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 30	        String dbUser = getEnv("DB_USER", "postgres");
 31	        String dbPassword = getEnv("DB_PASSWORD", "postgres");
 32	        int port = Integer.parseInt(getEnv("PORT", "7070"));
 33	
 34	        Database.initialize(dbUrl, dbUser, dbPassword);
 35	
 36	        RoomRepository roomRepository = new RoomRepository();
 37	        ReservationRepository reservationRepository = new ReservationRepository();
 38	        MessageRepository messageRepository = new MessageRepository();
 39	
 40	        initializeRooms(roomRepository);
 41	
 42	        EventPublisher eventPublisher = new EventPublisher();
 43	        eventPublisher.subscribe(new GuestNotificationListener(messageRepository, roomRepository));
 44	        eventPublisher.subscribe(new HousekeepingNotificationListener(messageRepository));
 45	        eventPublisher.subscribe(new FinanceNotificationListener(messageRepository));
 46	
 47	        RoomService roomService = new RoomService(roomRepository);
 48	        ReservationService reservationService = new ReservationService(
 49	            reservationRepository, roomRepository, eventPublisher
 50	        );
 51	        DocumentService documentService = new DocumentService(roomRepository);
 52	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 53	
 54	        RoomController roomController = new RoomController(roomService);
 55	        ReservationController reservationController = new ReservationController(
 56	            reservationService, documentService
 57	        );
 58	        MessageController messageController = new MessageController(messageRepository);
 59	        ReportController reportController = new ReportController(reportService);
 60	
 61	        ObjectMapper objectMapper = new ObjectMapper();
 62	        objectMapper.registerModule(new JavaTimeModule());
 63	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 64	
 65	        Javalin app = Javalin.create(config -> {
 66	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 67	        });
 68	
 69	        app.get("/rooms", roomController::getRooms);
 70	
 71	        app.post("/reservations", reservationController::createReservation);
 72	        app.get("/reservations/{id}", reservationController::getReservation);
 73	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 74	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 75	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 76	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 77	        app.get("/reservations/{id}/document", reservationController::getDocument);
 78	
 79	        app.get("/messages", messageController::getMessages);
 80	
 81	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 82	        app.get("/reports/revenue", reportController::getRevenueReport);
 83	
 84	        app.start(port);
 85	
 86	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 87	            app.stop();
 88	            Database.close();
 89	        }));
 90	    }
 91	
 92	    private static void initializeRooms(RoomRepository roomRepository) {
 93	        roomRepository.save(new Room("101", RoomType.STANDARD));
 94	        roomRepository.save(new Room("102", RoomType.STANDARD));
 95	        roomRepository.save(new Room("201", RoomType.DELUXE));
 96	        roomRepository.save(new Room("202", RoomType.DELUXE));
 97	        roomRepository.save(new Room("301", RoomType.SUITE));
 98	    }
 99	
100	    private static String getEnv(String name, String defaultValue) {
101	        String value = System.getenv(name);
102	        return value != null ? value : defaultValue;
103	    }
104	}
105	package com.pousadamarealta.config;
106	
107	import com.zaxxer.hikari.HikariConfig;
108	import com.zaxxer.hikari.HikariDataSource;
109	
110	import javax.sql.DataSource;
111	import java.sql.Connection;
112	import java.sql.SQLException;
113	import java.sql.Statement;
114	
115	public class Database {
116	    private static HikariDataSource dataSource;
117	
118	    public static void initialize(String jdbcUrl, String username, String password) {
119	        HikariConfig config = new HikariConfig();
120	        config.setJdbcUrl(jdbcUrl);
121	        config.setUsername(username);
122	        config.setPassword(password);
123	        config.setMaximumPoolSize(10);
124	        config.setAutoCommit(true);
125	
126	        dataSource = new HikariDataSource(config);
127	        createSchema();
128	    }
129	
130	    public static DataSource getDataSource() {
131	        if (dataSource == null) {
132	            throw new IllegalStateException("Database not initialized");
133	        }
134	        return dataSource;
135	    }
136	
137	    public static Connection getConnection() throws SQLException {
138	        return getDataSource().getConnection();
139	    }
140	
141	    public static void close() {
142	        if (dataSource != null && !dataSource.isClosed()) {
143	            dataSource.close();
144	        }
145	    }
146	
147	    private static void createSchema() {
148	        String schema = """
149	            CREATE TABLE IF NOT EXISTS rooms (
150	                number VARCHAR(10) PRIMARY KEY,
151	                type VARCHAR(20) NOT NULL
152	            );
153	
154	            CREATE TABLE IF NOT EXISTS reservations (
155	                id BIGSERIAL PRIMARY KEY,
156	                room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
157	                guest_name VARCHAR(255) NOT NULL,
158	                guest_email VARCHAR(255) NOT NULL,
159	                guest_cpf VARCHAR(11) NOT NULL,
160	                check_in DATE NOT NULL,
161	                check_out DATE NOT NULL,
162	                guests INTEGER NOT NULL,
163	                rate_plan VARCHAR(20) NOT NULL,
164	                nightly_rate DECIMAL(10, 2) NOT NULL,
165	                status VARCHAR(20) NOT NULL,
166	                amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
167	                refund DECIMAL(10, 2)
168	            );
169	
170	            CREATE TABLE IF NOT EXISTS messages (
171	                id BIGSERIAL PRIMARY KEY,
172	                channel VARCHAR(20) NOT NULL,
173	                recipient VARCHAR(255) NOT NULL,
174	                subject VARCHAR(500) NOT NULL,
175	                body TEXT NOT NULL
176	            );
177	
178	            CREATE INDEX IF NOT EXISTS idx_reservations_room_dates
179	                ON reservations(room_number, check_in, check_out);
180	            CREATE INDEX IF NOT EXISTS idx_reservations_status
181	                ON reservations(status);
182	            CREATE INDEX IF NOT EXISTS idx_reservations_check_in
183	                ON reservations(check_in);
184	            """;
185	
186	        try (Connection conn = getConnection();
187	             Statement stmt = conn.createStatement()) {
188	            stmt.execute(schema);
189	        } catch (SQLException e) {
190	            throw new RuntimeException("Failed to create database schema", e);
191	        }
192	    }
193	}
