218	import com.pousadamarealta.dto.ErrorResponse;
219	import com.pousadamarealta.service.ReportService;
220	import io.javalin.http.Context;
221	
222	import java.time.LocalDate;
223	import java.time.YearMonth;
224	import java.time.format.DateTimeFormatter;
225	import java.time.format.DateTimeParseException;
226	
227	public class ReportController {
228	    private final ReportService reportService;
229	
230	    public ReportController(ReportService reportService) {
231	        this.reportService = reportService;
232	    }
233	
234	    public void getOccupancyReport(Context ctx) {
235	        try {
236	            String dateParam = ctx.queryParam("date");
237	            if (dateParam == null || dateParam.isBlank()) {
238	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
239	                return;
240	            }
241	
242	            LocalDate date = LocalDate.parse(dateParam, DateTimeFormatter.ISO_LOCAL_DATE);
243	            String csv = reportService.generateOccupancyReport(date);
244	
245	            ctx.contentType("text/csv; charset=utf-8")
246	               .result(csv);
247	        } catch (DateTimeParseException e) {
248	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
249	        }
250	    }
251	
252	    public void getRevenueReport(Context ctx) {
253	        try {
254	            String monthParam = ctx.queryParam("month");
255	            if (monthParam == null || monthParam.isBlank()) {
256	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
257	                return;
258	            }
259	
260	            YearMonth yearMonth = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
261	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
262	
263	            ctx.contentType("text/csv; charset=utf-8")
264	               .result(csv);
265	        } catch (DateTimeParseException e) {
266	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
267	        }
268	    }
269	}
270	package com.pousadamarealta.controller;
