118	    public static void initialize(String jdbcUrl, String username, String password) {
119	        HikariConfig config = new HikariConfig();
120	        config.setJdbcUrl(jdbcUrl);
121	        config.setUsername(username);
122	        config.setPassword(password);
123	        config.setMaximumPoolSize(10);
124	        config.setAutoCommit(true);
125	
126	        dataSource = new HikariDataSource(config);
127	        createSchema();
128	    }
129	
130	    public static DataSource getDataSource() {
131	        if (dataSource == null) {
132	            throw new IllegalStateException("Database not initialized");
133	        }
134	        return dataSource;
135	    }
136	
137	    public static Connection getConnection() throws SQLException {
138	        return getDataSource().getConnection();
139	    }
140	
141	    public static void close() {
142	        if (dataSource != null && !dataSource.isClosed()) {
143	            dataSource.close();
144	        }
145	    }
146	
147	    private static void createSchema() {
148	        String schema = """
149	            CREATE TABLE IF NOT EXISTS rooms (
150	                number VARCHAR(10) PRIMARY KEY,
151	                type VARCHAR(20) NOT NULL
152	            );
153	
154	            CREATE TABLE IF NOT EXISTS reservations (
155	                id BIGSERIAL PRIMARY KEY,
156	                room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
157	                guest_name VARCHAR(255) NOT NULL,
158	                guest_email VARCHAR(255) NOT NULL,
159	                guest_cpf VARCHAR(11) NOT NULL,
160	                check_in DATE NOT NULL,
161	                check_out DATE NOT NULL,
162	                guests INTEGER NOT NULL,
163	                rate_plan VARCHAR(20) NOT NULL,
164	                nightly_rate DECIMAL(10, 2) NOT NULL,
165	                status VARCHAR(20) NOT NULL,
166	                amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
167	                refund DECIMAL(10, 2)
168	            );
169	
170	            CREATE TABLE IF NOT EXISTS messages (
171	                id BIGSERIAL PRIMARY KEY,
172	                channel VARCHAR(20) NOT NULL,
173	                recipient VARCHAR(255) NOT NULL,
174	                subject VARCHAR(500) NOT NULL,
175	                body TEXT NOT NULL
176	            );
177	
178	            CREATE INDEX IF NOT EXISTS idx_reservations_room_dates
179	                ON reservations(room_number, check_in, check_out);
180	            CREATE INDEX IF NOT EXISTS idx_reservations_status
181	                ON reservations(status);
182	            CREATE INDEX IF NOT EXISTS idx_reservations_check_in
183	                ON reservations(check_in);
184	            """;
185	
186	        try (Connection conn = getConnection();
187	             Statement stmt = conn.createStatement()) {
188	            stmt.execute(schema);
189	        } catch (SQLException e) {
190	            throw new RuntimeException("Failed to create database schema", e);
191	        }
192	    }
193	}
