159	import java.math.BigDecimal;
160	import java.math.RoundingMode;
161	import java.time.LocalDate;
162	import java.time.temporal.ChronoUnit;
163	
164	public class Reservation {
165	    private Long id;
166	    private final String roomNumber;
167	    private final String guestName;
168	    private final String guestEmail;
169	    private final String guestCpf;
170	    private final LocalDate checkIn;
171	    private final LocalDate checkOut;
172	    private final int guests;
173	    private final RatePlan ratePlan;
174	    private final BigDecimal nightlyRate;
175	    private ReservationStatus status;
176	    private BigDecimal amountPaid;
177	    private BigDecimal refund;
178	
179	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
180	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
181	                      BigDecimal nightlyRate, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
182	        this.id = id;
183	        this.roomNumber = roomNumber;
184	        this.guestName = guestName;
185	        this.guestEmail = guestEmail;
186	        this.guestCpf = guestCpf;
187	        this.checkIn = checkIn;
188	        this.checkOut = checkOut;
189	        this.guests = guests;
190	        this.ratePlan = ratePlan;
191	        this.nightlyRate = nightlyRate;
192	        this.status = status;
193	        this.amountPaid = amountPaid;
194	        this.refund = refund;
195	    }
196	
197	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
198	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
199	                                    BigDecimal nightlyRate) {
200	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
201	                guests, ratePlan, nightlyRate, ReservationStatus.PENDING, BigDecimal.ZERO, null);
202	    }
203	
204	    public void setId(Long id) {
205	        this.id = id;
206	    }
207	
208	    public Long getId() {
209	        return id;
210	    }
211	
212	    public String getRoomNumber() {
213	        return roomNumber;
214	    }
215	
216	    public String getGuestName() {
217	        return guestName;
218	    }
219	
220	    public String getGuestEmail() {
221	        return guestEmail;
222	    }
223	
224	    public String getGuestCpf() {
225	        return guestCpf;
226	    }
227	
228	    public LocalDate getCheckIn() {
229	        return checkIn;
230	    }
231	
232	    public LocalDate getCheckOut() {
233	        return checkOut;
234	    }
235	
236	    public int getGuests() {
237	        return guests;
238	    }
239	
240	    public RatePlan getRatePlan() {
241	        return ratePlan;
242	    }
243	
244	    public BigDecimal getNightlyRate() {
245	        return nightlyRate;
246	    }
247	
248	    public ReservationStatus getStatus() {
249	        return status;
250	    }
251	
252	    public BigDecimal getAmountPaid() {
253	        return amountPaid;
254	    }
255	
256	    public BigDecimal getRefund() {
257	        return refund;
258	    }
259	
260	    public int getNights() {
261	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
262	    }
263	
264	    public BigDecimal getSubtotal() {
265	        return nightlyRate.multiply(new BigDecimal(getNights()))
266	                .setScale(2, RoundingMode.HALF_EVEN);
267	    }
268	
269	    public BigDecimal getDiscount() {
270	        BigDecimal subtotal = getSubtotal();
271	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
272	                .setScale(2, RoundingMode.HALF_EVEN);
273	        return discount;
274	    }
275	
276	    public BigDecimal getTotal() {
277	        return getSubtotal().subtract(getDiscount())
278	                .setScale(2, RoundingMode.HALF_EVEN);
279	    }
280	
281	    public void confirm() {
282	        if (status != ReservationStatus.PENDING) {
283	            throw new IllegalStateException("Only pending reservations can be confirmed");
284	        }
285	        this.status = ReservationStatus.CONFIRMED;
286	        this.amountPaid = getTotal();
287	    }
288	
289	    public void cancel() {
290	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
291	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
292	        }
293	
294	        boolean wasConfirmed = status == ReservationStatus.CONFIRMED;
295	        this.status = ReservationStatus.CANCELLED;
296	
297	        if (wasConfirmed && ratePlan == RatePlan.STANDARD) {
298	            this.refund = amountPaid;
299	        } else {
300	            this.refund = BigDecimal.ZERO;
301	        }
302	    }
303	
304	    public void checkIn() {
305	        if (status != ReservationStatus.CONFIRMED) {
306	            throw new IllegalStateException("Only confirmed reservations can be checked in");
307	        }
308	        this.status = ReservationStatus.CHECKED_IN;
309	    }
310	
311	    public void checkOut() {
312	        if (status != ReservationStatus.CHECKED_IN) {
313	            throw new IllegalStateException("Only checked-in reservations can be checked out");
314	        }
315	        this.status = ReservationStatus.CHECKED_OUT;
316	    }
317	
318	    public boolean isActive() {
319	        return status != ReservationStatus.CANCELLED;
320	    }
321	
322	    public boolean isPaid() {
323	        return status == ReservationStatus.CONFIRMED ||
