164	public class Reservation {
165	    private Long id;
166	    private final String roomNumber;
167	    private final String guestName;
168	    private final String guestEmail;
169	    private final String guestCpf;
170	    private final LocalDate checkIn;
171	    private final LocalDate checkOut;
172	    private final int guests;
173	    private final RatePlan ratePlan;
174	    private final BigDecimal nightlyRate;
175	    private ReservationStatus status;
176	    private BigDecimal amountPaid;
177	    private BigDecimal refund;
178	
179	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
180	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
181	                      BigDecimal nightlyRate, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
182	        this.id = id;
183	        this.roomNumber = roomNumber;
184	        this.guestName = guestName;
185	        this.guestEmail = guestEmail;
186	        this.guestCpf = guestCpf;
187	        this.checkIn = checkIn;
188	        this.checkOut = checkOut;
189	        this.guests = guests;
190	        this.ratePlan = ratePlan;
191	        this.nightlyRate = nightlyRate;
192	        this.status = status;
193	        this.amountPaid = amountPaid;
194	        this.refund = refund;
195	    }
196	
197	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
198	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
199	                                    BigDecimal nightlyRate) {
200	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
201	                guests, ratePlan, nightlyRate, ReservationStatus.PENDING, BigDecimal.ZERO, null);
202	    }
203	
204	    public void setId(Long id) {
205	        this.id = id;
206	    }
207	
208	    public Long getId() {
209	        return id;
210	    }
211	
212	    public String getRoomNumber() {
213	        return roomNumber;
214	    }
215	
216	    public String getGuestName() {
217	        return guestName;
218	    }
219	
220	    public String getGuestEmail() {
221	        return guestEmail;
222	    }
223	
224	    public String getGuestCpf() {
225	        return guestCpf;
226	    }
