260	    public int getNights() {
261	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
262	    }
263	
264	    public BigDecimal getSubtotal() {
265	        return nightlyRate.multiply(new BigDecimal(getNights()))
266	                .setScale(2, RoundingMode.HALF_EVEN);
267	    }
268	
269	    public BigDecimal getDiscount() {
270	        BigDecimal subtotal = getSubtotal();
271	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
272	                .setScale(2, RoundingMode.HALF_EVEN);
273	        return discount;
274	    }
275	
276	    public BigDecimal getTotal() {
277	        return getSubtotal().subtract(getDiscount())
278	                .setScale(2, RoundingMode.HALF_EVEN);
279	    }
280	
281	    public void confirm() {
282	        if (status != ReservationStatus.PENDING) {
283	            throw new IllegalStateException("Only pending reservations can be confirmed");
284	        }
285	        this.status = ReservationStatus.CONFIRMED;
286	        this.amountPaid = getTotal();
287	    }
288	
289	    public void cancel() {
290	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
291	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
292	        }
293	
294	        boolean wasConfirmed = status == ReservationStatus.CONFIRMED;
295	        this.status = ReservationStatus.CANCELLED;
296	
297	        if (wasConfirmed && ratePlan == RatePlan.STANDARD) {
298	            this.refund = amountPaid;
299	        } else {
300	            this.refund = BigDecimal.ZERO;
301	        }
302	    }
303	
304	    public void checkIn() {
305	        if (status != ReservationStatus.CONFIRMED) {
306	            throw new IllegalStateException("Only confirmed reservations can be checked in");
307	        }
308	        this.status = ReservationStatus.CHECKED_IN;
309	    }
