 91	public class GuestNotificationListener implements EventListener {
 92	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 93	    private static final DecimalFormat MONEY_FORMATTER;
 94	
 95	    static {
 96	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
 97	        symbols.setGroupingSeparator('.');
 98	        symbols.setDecimalSeparator(',');
 99	        MONEY_FORMATTER = new DecimalFormat("#,##0.00", symbols);
100	    }
101	
102	    private final MessageRepository messageRepository;
103	    private final RoomRepository roomRepository;
104	
105	    public GuestNotificationListener(MessageRepository messageRepository, RoomRepository roomRepository) {
106	        this.messageRepository = messageRepository;
107	        this.roomRepository = roomRepository;
108	    }
109	
110	    @Override
111	    public void handle(ReservationEvent event) {
112	        if (event instanceof ReservationConfirmedEvent) {
113	            sendConfirmationEmail((ReservationConfirmedEvent) event);
114	        }
115	    }
116	
117	    private void sendConfirmationEmail(ReservationConfirmedEvent event) {
118	        Reservation reservation = event.getReservation();
119	        RoomType roomType = roomRepository.findByNumber(reservation.getRoomNumber())
120	                .orElseThrow()
121	                .getType();
122	
123	        String receipt = buildReceipt(reservation, roomType);
124	        String body = buildConfirmationBody(reservation.getGuestName(), receipt);
125	
126	        Message message = Message.email(
127	            reservation.getGuestEmail(),
128	            "Reserva confirmada - Pousada Maré Alta",
129	            body
130	        );
131	
132	        messageRepository.save(message);
133	    }
134	
135	    private String buildReceipt(Reservation reservation, RoomType roomType) {
136	        StringBuilder sb = new StringBuilder();
137	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
138	        sb.append("Hóspede: ").append(reservation.getGuestName())
139	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
140	        sb.append("Quarto: ").append(reservation.getRoomNumber())
141	          .append(" (").append(roomType).append(")\n");
142	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
143	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
144	          .append(" | ").append(reservation.getNights())
145	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
146	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
147	
148	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
149	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
150	        }
151	
152	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
153	
154	        return sb.toString();
155	    }
156	
157	    private String buildConfirmationBody(String guestName, String receipt) {
158	        return String.format(
159	            "Olá, %s!\n\n" +
160	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
161	            "%s\n\n" +
162	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
163	            "Até breve!",
164	            guestName, receipt
165	        );
166	    }
167	
168	    private String formatDate(LocalDate date) {
169	        return date.format(DATE_FORMATTER);
170	    }
171	
172	    private String formatMoney(BigDecimal amount) {
173	        return "R$ " + MONEY_FORMATTER.format(amount);
174	    }
175	
176	    private String formatCpf(String cpf) {
177	        if (cpf.length() == 11) {
178	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
179	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
180	        }
181	        return cpf;
182	    }
183	}
