 27	    private final MessageRepository messageRepository;
 28	
 29	    public FinanceNotificationListener(MessageRepository messageRepository) {
 30	        this.messageRepository = messageRepository;
 31	    }
 32	
 33	    @Override
 34	    public void handle(ReservationEvent event) {
 35	        if (event instanceof ReservationConfirmedEvent) {
 36	            notifyPayment((ReservationConfirmedEvent) event);
 37	        } else if (event instanceof ReservationCancelledEvent cancelledEvent) {
 38	            if (cancelledEvent.wasConfirmed() && hasRefund(cancelledEvent.getReservation())) {
 39	                notifyRefund(cancelledEvent);
 40	            }
 41	        }
 42	    }
 43	
 44	    private void notifyPayment(ReservationConfirmedEvent event) {
 45	        Reservation reservation = event.getReservation();
 46	
 47	        String subject = String.format("Pagamento recebido - reserva %d", reservation.getId());
 48	        String body = formatMoney(reservation.getAmountPaid());
 49	
 50	        Message message = Message.email(FINANCE_EMAIL, subject, body);
 51	        messageRepository.save(message);
 52	    }
 53	
 54	    private void notifyRefund(ReservationCancelledEvent event) {
 55	        Reservation reservation = event.getReservation();
 56	
 57	        String subject = String.format("Reembolso - reserva %d", reservation.getId());
 58	        String body = formatMoney(reservation.getRefund());
 59	
 60	        Message message = Message.email(FINANCE_EMAIL, subject, body);
 61	        messageRepository.save(message);
 62	    }
 63	
 64	    private boolean hasRefund(Reservation reservation) {
 65	        return reservation.getRefund() != null &&
 66	               reservation.getRefund().compareTo(BigDecimal.ZERO) > 0;
 67	    }
 68	
 69	    private String formatMoney(BigDecimal amount) {
 70	        return "R$ " + MONEY_FORMATTER.format(amount);
 71	    }
