  7	import java.sql.Connection;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.SQLException;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	
 14	public class MessageRepository {
 15	
 16	    public Message save(Message message) {
 17	        String sql = """
 18	            INSERT INTO messages (channel, recipient, subject, body)
 19	            VALUES (?, ?, ?, ?)
 20	            RETURNING id
 21	            """;
 22	
 23	        try (Connection conn = Database.getConnection();
 24	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 25	
 26	            stmt.setString(1, message.getChannel().name());
 27	            stmt.setString(2, message.getTo());
 28	            stmt.setString(3, message.getSubject());
 29	            stmt.setString(4, message.getBody());
 30	
 31	            try (ResultSet rs = stmt.executeQuery()) {
 32	                if (rs.next()) {
 33	                    message.setId(rs.getLong("id"));
 34	                }
 35	            }
 36	
 37	            return message;
 38	        } catch (SQLException e) {
 39	            throw new RuntimeException("Failed to save message", e);
 40	        }
 41	    }
 42	
 43	    public List<Message> findAll() {
 44	        String sql = "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id";
 45	        List<Message> messages = new ArrayList<>();
 46	
 47	        try (Connection conn = Database.getConnection();
 48	             PreparedStatement stmt = conn.prepareStatement(sql);
 49	             ResultSet rs = stmt.executeQuery()) {
 50	
 51	            while (rs.next()) {
 52	                messages.add(mapRow(rs));
 53	            }
 54	        } catch (SQLException e) {
 55	            throw new RuntimeException("Failed to list messages", e);
 56	        }
 57	
 58	        return messages;
 59	    }
 60	
 61	    private Message mapRow(ResultSet rs) throws SQLException {
 62	        return new Message(
 63	            rs.getLong("id"),
 64	            MessageChannel.valueOf(rs.getString("channel")),
 65	            rs.getString("recipient"),
 66	            rs.getString("subject"),
 67	            rs.getString("body")
 68	        );
 69	    }
 70	}
