 87	    public Reservation save(Reservation reservation) {
 88	        if (reservation.getId() == null) {
 89	            return insert(reservation);
 90	        } else {
 91	            return update(reservation);
 92	        }
 93	    }
 94	
 95	    private Reservation insert(Reservation reservation) {
 96	        String sql = """
 97	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 98	                                     check_in, check_out, guests, rate_plan, nightly_rate,
 99	                                     status, amount_paid, refund)
100	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
101	            RETURNING id
102	            """;
103	
104	        try (Connection conn = Database.getConnection();
105	             PreparedStatement stmt = conn.prepareStatement(sql)) {
106	
107	            setStatementParameters(stmt, reservation);
108	
109	            try (ResultSet rs = stmt.executeQuery()) {
110	                if (rs.next()) {
111	                    reservation.setId(rs.getLong("id"));
112	                }
113	            }
114	
115	            return reservation;
116	        } catch (SQLException e) {
117	            throw new RuntimeException("Failed to insert reservation", e);
118	        }
119	    }
120	
121	    private Reservation update(Reservation reservation) {
122	        String sql = """
123	            UPDATE reservations
124	            SET room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
125	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?, nightly_rate = ?,
126	                status = ?, amount_paid = ?, refund = ?
127	            WHERE id = ?
128	            """;
129	
130	        try (Connection conn = Database.getConnection();
131	             PreparedStatement stmt = conn.prepareStatement(sql)) {
132	
133	            setStatementParameters(stmt, reservation);
134	            stmt.setLong(13, reservation.getId());
135	            stmt.executeUpdate();
136	
137	            return reservation;
138	        } catch (SQLException e) {
139	            throw new RuntimeException("Failed to update reservation", e);
140	        }
