   209	    static class InMemoryRoomRepository extends RoomRepository {
   210	        private final List<Room> rooms = new ArrayList<>();
   211	
   212	        @Override
   213	        public void save(Room room) {
   214	            rooms.removeIf(r -> r.getNumber().equals(room.getNumber()));
   215	            rooms.add(room);
   216	        }
   217	
   218	        @Override
   219	        public Optional<Room> findByNumber(String number) {
   220	            return rooms.stream()
   221	                    .filter(r -> r.getNumber().equals(number))
   222	                    .findFirst();
   223	        }
   224	
   225	        @Override
   226	        public List<Room> findAll() {
   227	            return new ArrayList<>(rooms);
   228	        }
   229	    }
